-/* ---------- file map ---------- */
-.files { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; }
-.fcard {
-  background: var(--panel); border: 1px solid var(--line); border-radius: 12px;
-  padding: 16px 18px; transition: border-color 0.2s, transform 0.2s;
-}
-.fcard:hover { border-color: rgba(46,230,200,0.45); transform: translateY(-2px); }
-.fcard .path { font-family: var(--mono); font-size: 12px; color: var(--accent); word-break: break-all; }
-.fcard p { font-size: 13px; color: var(--muted); margin-top: 7px; line-height: 1.55; }
-
-footer {
-  padding: 50px 0 70px; color: var(--muted);
-  font-family: var(--mono); font-size: 12px; letter-spacing: 0.08em;
