-    { side: "user",  h: 44, label: "How do bubbles stack?" },
-    { side: "agent", h: 88, label: "Column flow: y is margin,\nx is yours to keep." },
-    { side: "user",  h: 44, label: "And the overflow?" },
-    { side: "agent", h: 72, label: "Scissor-clipped. Offset\nclamped every frame." },
